using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// The MCP SDK discovers tools via [McpServerToolType] on the class
/// and [McpServerTool] on each public method.
/// Constructor parameters are resolved from DI automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // The MCP SDK resolves constructor dependencies from the DI container.
    // Because we register a named HttpClient ("Weather"), we inject IHttpClientFactory
    // and create the client by name.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _http = httpClientFactory.CreateClient("Weather");
    }

    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";

        var response = await _http.GetFromJsonAsync<WeatherResponse>(url);
        if (response?.CurrentWeather is null)
            return "Unable to fetch weather data.";

        var w = response.CurrentWeather;
        return $"Temperature: {w.Temperature}°C, Wind: {w.WindSpeed} km/h, Direction: {w.WindDirection}°";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a location.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        [Description("Number of forecast days (1-7)")] int days = 3)
    {
        days = Math.Clamp(days, 1, 7);
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}" +
                  $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";

        var response = await _http.GetFromJsonAsync<ForecastResponse>(url);
        if (response?.Daily is null)
            return "Unable to fetch forecast data.";

        var lines = new List<string>();
        for (int i = 0; i < response.Daily.Time.Count; i++)
        {
            lines.Add($"{response.Daily.Time[i]}: High {response.Daily.TemperatureMax[i]}°C, Low {response.Daily.TemperatureMin[i]}°C");
        }
        return string.Join("\n", lines);
    }
}

// --- JSON models for the Open-Meteo API ---

public record WeatherResponse
{
    [JsonPropertyName("current_weather")]
    public CurrentWeather? CurrentWeather { get; init; }
}

public record CurrentWeather
{
    [JsonPropertyName("temperature")]
    public double Temperature { get; init; }

    [JsonPropertyName("windspeed")]
    public double WindSpeed { get; init; }

    [JsonPropertyName("winddirection")]
    public double WindDirection { get; init; }
}

public record ForecastResponse
{
    [JsonPropertyName("daily")]
    public DailyForecast? Daily { get; init; }
}

public record DailyForecast
{
    [JsonPropertyName("time")]
    public List<string> Time { get; init; } = [];

    [JsonPropertyName("temperature_2m_max")]
    public List<double> TemperatureMax { get; init; } = [];

    [JsonPropertyName("temperature_2m_min")]
    public List<double> TemperatureMin { get; init; } = [];
}

