using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

// Register a named HttpClient with a base address and default headers.
builder.Services.AddHttpClient("Weather", client =>
{
    client.DefaultRequestHeaders.UserAgent.ParseAdd("McpWeatherServer/1.0");
});

// Register the MCP server using stdio transport.
// WithTools<T>() registers the tool class AND adds it to DI as transient.
builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithTools<WeatherTools>();

await builder.Build().RunAsync();

